solution.solution.cpp:
#include <algorithm>
#include <functional>
#include <optional>

class FakeClock
{
public:
    double now() const { return m_time; }
    void advance(double seconds) { m_time += seconds; }
private:
    double m_time{ 0.0 };
};

class Cooldown
{
public:
    Cooldown(std::function<double()> clock, double duration) : m_clock{ std::move(clock) }, m_duration{ duration } {}

    bool ready() const { return remaining() <= 0.0; }

    bool use()
    {
        if (!ready()) return false;
        m_lastUse = m_clock();
        return true;
    }

    double remaining() const
    {
        if (!m_lastUse) return 0.0;
        return std::max(0.0, *m_lastUse + m_duration - m_clock());
    }

private:
    std::function<double()> m_clock;
    double m_duration;
    std::optional<double> m_lastUse;
};

unitTests:
TEST("ready before first use") { FakeClock c; Cooldown cd{ [&] { return c.now(); }, 2.0 }; CHECK(cd.ready()); CHECK_NEAR(cd.remaining(), 0.0, 1e-12); }
TEST("not ready right after use") { FakeClock c; Cooldown cd{ [&] { return c.now(); }, 2.0 }; CHECK(cd.use()); CHECK(!cd.ready()); CHECK(!cd.use()); CHECK_NEAR(cd.remaining(), 2.0, 1e-12); }
TEST("time passes") { FakeClock c; Cooldown cd{ [&] { return c.now(); }, 2.0 }; cd.use(); c.advance(1.5); CHECK_NEAR(cd.remaining(), 0.5, 1e-12); CHECK(!cd.ready()); c.advance(0.5); CHECK(cd.ready()); CHECK(cd.use()); }
TEST("a failed use does not restart the cooldown") { FakeClock c; Cooldown cd{ [&] { return c.now(); }, 2.0 }; cd.use(); c.advance(1.0); cd.use(); c.advance(1.0); CHECK(cd.ready()); }
TEST("the fake clock") { FakeClock c; c.advance(3.25); c.advance(0.75); CHECK_NEAR(c.now(), 4.0, 1e-12); }

